/* 悬浮音乐播放器 — by 桃mini · 只搜歌、听歌，无需填写音频链接。
 * Public Meting protocol: https://api.qijieya.cn/meting/ ; https://api.injahow.cn/meting/
 * 不依赖消息、角色卡或聊天状态；在酒馆助手全局脚本库运行。
 */
(() => {
  'use strict';
  const host = window.parent;
  const doc = host.document;
  const SLOT = '__taominiFloatingMusicV1';
  host[SLOT]?.destroy();
  // 升级原脚本时移除旧实例；旧歌单数据不作改动。
  host.__swipeMusicPlayerV1?.destroy?.();
  const STORE = '$taominiFloatingMusic';
  const BACKUP_STORE = 'taomini-floating-music-library-v1';
  let browserBackupFailed = false, restoredBrowserBackup = false;
  const API = 'https://api.qijieya.cn/meting/';
  const BACKUP = 'https://api.injahow.cn/meting/';
  const PLATFORMS = [{ id: 'netease', name: '网易云' }, { id: 'tencent', name: 'QQ 音乐' }];
  const read = typeof getVariables === 'function' ? getVariables : null;
  const write = typeof updateVariablesWith === 'function' ? updateVariablesWith : null;
  const scope = { type: 'script', ...(typeof getScriptId === 'function' ? { script_id: getScriptId() } : {}) };
  let saved = {};
  try { saved = read?.(scope)?.[STORE] || {}; } catch { /* 变量暂不可读时仍可搜歌。 */ }
  if (!saved || typeof saved !== 'object' || Array.isArray(saved)) saved = {};
  try {
    const backup = JSON.parse(host.localStorage.getItem(BACKUP_STORE) || 'null');
    const value = backup?.saved;
    if (value && typeof value === 'object' && !Array.isArray(value) && Array.isArray(value.playlists)
      && (!Array.isArray(saved.playlists) || Number(value.updatedAt || 0) > Number(saved.updatedAt || 0))) {
      saved = value; restoredBrowserBackup = true;
    }
  } catch { /* 浏览器备份不可读时仍读取原脚本变量。 */ }

  let showDockLyrics = saved.showDockLyrics !== false;
  let dockIconData = validDockIcon(saved.dockIconData) ? saved.dockIconData : '';
  let dead = false, folded = saved.folded === true;
  let position = saved.position && Number.isFinite(saved.position.x) && Number.isFinite(saved.position.y)
    ? { x: saved.position.x, y: saved.position.y } : null;
  let results = [], queue = [], current = null, library = [], favorites = [], playlists = [];
  let selectedPlaylistId = typeof saved.selectedPlaylistId === 'string' ? saved.selectedPlaylistId : 'default';
  let queuePlaylistId = typeof saved.queuePlaylistId === 'string' ? saved.queuePlaylistId : 'default';
  let queueMode = ['playlist', 'favorites'].includes(saved.queueMode) ? saved.queueMode : 'search';
  const PLAY_MODES = [{ id: 'sequence', label: '顺序播放', icon: '⇥' }, { id: 'list', label: '列表循环', icon: '↻' }, { id: 'one', label: '单曲循环', icon: '↻₁' }, { id: 'random', label: '随机播放', icon: '⤨' }];
  let playMode = PLAY_MODES.some(mode => mode.id === saved.playMode) ? saved.playMode : 'list';
  let libraryRevision = 0, libraryDirty = false;
  let intent = false, loading = false, searching = false, playRevision = 0, searchRevision = 0;
  let libraryLimit = 30, favoritesLimit = 30;
  let importJob = null;
  let playJob = null, searchJob = null, activeAttempt = null, activeVariant = -1;
  let status = '等待播放';
  let saveTimer = 0, pendingWrite = Promise.resolve(), drag = null, movedAt = 0;
  let saveWarning = false, proxyUnavailable = false;
  const controllers = new Set();
  const mp3Cache = new Map();
  const MAX_MP3_BYTES = 24 * 1024 * 1024;
  const MAX_CACHE_BYTES = 96 * 1024 * 1024;
  const pendingMP3 = new Map();
  let prefetchJob = null;
  let activeBlobURL = '';
  const audio = new host.Audio();
  audio.preload = 'auto';
  audio.volume = 0.45;
  const panel = doc.createElement('div');
  panel.id = 'taomini-floating-music';
  panel.style.cssText = 'position:fixed;z-index:2147483000;right:18px;bottom:calc(88px + env(safe-area-inset-bottom,0px));display:block;max-width:calc(100vw - 20px);isolation:isolate;';
  const root = panel.attachShadow({ mode: 'open' });
  root.innerHTML = `
    <style>
      :host{--fg:var(--SmartThemeBodyColor,#e6e5e9);--base:var(--SmartThemeBlurTintColor,#24242b);--muted:color-mix(in srgb,var(--fg) 58%,transparent);--line:color-mix(in srgb,var(--fg) 13%,transparent);--soft:color-mix(in srgb,var(--fg) 6%,transparent);color:var(--fg);font:13px/1.5 var(--mainFontFamily,system-ui),"Microsoft YaHei",sans-serif;text-align:left;color-scheme:dark light}
      *{box-sizing:border-box}button,input{font:inherit;color:inherit}button{cursor:pointer;background:transparent;border:0;display:inline-flex;align-items:center;justify-content:center;padding:0;flex-shrink:0;touch-action:manipulation;-webkit-tap-highlight-color:transparent}button:disabled{opacity:.3;cursor:default}button:hover{background:var(--soft)}button:focus-visible{outline:1px solid var(--line);outline-offset:2px}input:focus,textarea:focus,select:focus{outline:none!important;box-shadow:none!important}[hidden]{display:none!important}
      .window{width:344px;max-width:calc(100vw - 20px);height:min(560px,calc(100dvh - 28px),var(--available-height,100dvh));max-height:min(calc(100dvh - 28px),var(--available-height,100dvh));display:flex;flex-direction:column;border:1px solid var(--line);border-radius:17px;overflow:hidden;background:#24242b;background:rgb(from var(--base) r g b / 1);box-shadow:0 12px 45px #0002}
      .header{flex-shrink:0;display:flex;align-items:center;gap:8px;padding:12px 14px 9px;user-select:none;touch-action:none;cursor:grab}.header:active{cursor:grabbing}.brand{font-size:12px;font-weight:550;letter-spacing:.3px;flex:1}.mark{font-size:18px;color:var(--muted)}.minimize{width:28px;height:28px;border-radius:8px;font-size:18px;color:var(--muted)}
      .player{flex-shrink:0;padding:4px 16px 12px}.now{display:flex;align-items:center;gap:10px;min-width:0}.meta{flex:1;min-width:0}.title{font-weight:550;font-size:14px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.artist{color:var(--muted);font-size:11px;min-height:17px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;margin-top:2px}.controls{display:flex;align-items:center;gap:2px}.controls button{width:28px;height:32px;border-radius:8px}.controls .play{width:36px;height:36px;margin:0 3px;border:1px solid var(--line);border-radius:50%;background:var(--soft);font-size:14px}.controls svg{width:14px;height:14px;fill:currentColor}
      .timeline{display:flex;align-items:center;gap:8px;color:var(--muted);font:10px/1.5 ui-monospace,monospace;font-variant-numeric:tabular-nums;margin-top:10px}.timeline span{min-width:28px}.duration{text-align:right}.seek{--fill:0%;appearance:none;-webkit-appearance:none;flex:1;min-width:0;width:100%;margin:0;height:18px;background:transparent;cursor:pointer}.seek:disabled{opacity:.3;cursor:default}.seek::-webkit-slider-runnable-track{height:2px;border-radius:2px;background:linear-gradient(to right,var(--fg) var(--fill),var(--line) var(--fill))}.seek::-webkit-slider-thumb{appearance:none;-webkit-appearance:none;width:7px;height:7px;border-radius:50%;border:0;background:var(--fg);margin-top:-2.5px}.seek::-moz-range-track{height:2px;background:var(--line)}.seek::-moz-range-progress{height:2px;background:var(--fg)}.seek::-moz-range-thumb{width:7px;height:7px;border:0;border-radius:50%;background:var(--fg)}
      .status{margin:5px 0 0;min-height:16px;font-size:10px;line-height:1.6;color:var(--muted);overflow-wrap:anywhere}.search-area{padding:0 16px 12px;min-height:0;flex:1;overflow-y:auto;overscroll-behavior:contain;display:flex;flex-direction:column}.search-form{display:flex;align-items:center;gap:8px;border-top:1px solid var(--line);padding-top:12px;flex-shrink:0}.query{min-width:0;flex:1;width:100%;border:1px solid var(--line);border-radius:9px;background:transparent;padding:9px 10px;font-size:12px}.query::placeholder{color:var(--muted)}.search-button{border:1px solid var(--line);border-radius:9px;padding:0 12px;height:37px;font-size:11px;white-space:nowrap}.search-status{font-size:10px;line-height:1.6;color:var(--muted);margin:8px 0 4px;flex-shrink:0;overflow-wrap:anywhere}.results{overflow-y:auto;overscroll-behavior:contain;max-height:min(310px,42dvh);min-height:0;scrollbar-width:thin;scrollbar-color:var(--line) transparent}.empty{padding:24px 6px 26px;text-align:center;color:var(--muted);font-size:11px}.result{display:flex;align-items:center;width:100%;text-align:left;gap:10px;border-radius:9px;padding:9px 7px;min-height:53px}.result.active{background:var(--soft)}.number{width:20px;flex-shrink:0;text-align:center;color:var(--muted);font:10px ui-monospace,monospace}.result-info{flex:1;min-width:0}.result-title{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:12px}.result-artist{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:10px;color:var(--muted);margin-top:2px}.result-icon{font-size:11px;width:17px;color:var(--muted)}
      .dock{height:44px;width:44px;display:flex;align-items:center;justify-content:center;gap:10px;padding:0;border-radius:20px;background:transparent;border:0;box-shadow:none;touch-action:none;user-select:none;text-align:left}.dock.has-lyrics{border-radius:999px;overflow:hidden;background:rgb(from var(--base) r g b / .8);border:1px solid var(--line);width:260px;max-width:calc(100vw - 20px);height:58px;padding:8px 13px;justify-content:flex-start}.dock:hover,.dock:active{background:transparent}.dock.has-lyrics:hover,.dock.has-lyrics:active{background:rgb(from var(--base) r g b / .8)}.dock-lyrics{display:none;min-width:0;flex:1;pointer-events:none}.dock.has-lyrics .dock-lyrics{display:block}.dock .dock-note{pointer-events:none}.dock-note{font-size:23px;flex-shrink:0}.dock.playing .dock-note{color:var(--fg)}.dock.paused .dock-note{color:var(--muted)}
      .lists{flex:1;min-height:100px;overflow-y:auto;overscroll-behavior:contain;scrollbar-width:thin;scrollbar-color:var(--line) transparent}.lists .results{overflow:visible;max-height:none}.search-drawer,.playlist-drawer{border-top:1px solid var(--line);margin-top:9px}.lists summary{display:flex;align-items:center;gap:7px;cursor:pointer;list-style:none;padding:9px 2px;color:var(--muted);font-size:11px;user-select:none}.lists summary::-webkit-details-marker{display:none}.lists summary::after{content:'⌄';margin-left:auto}.lists details[open]>summary::after{content:'⌃'}.list-count{font:10px ui-monospace,monospace}.search-row,.playlist-row{display:flex;align-items:center;gap:3px}.search-row .result,.playlist-row .result{flex:1;min-width:0;width:0}.add-song,.remove-song{width:30px;height:32px;border-radius:8px;font-size:18px;color:var(--muted)}.add-song:disabled{opacity:.5;font-size:12px}.remove-song{font-size:15px}.playlist-status{margin:0 2px 4px;color:var(--muted);font-size:10px;line-height:1.6}.playlist-status:empty{display:none}.retry-save{font-size:10px;padding:4px 8px;border:1px solid var(--line);border-radius:7px;margin-bottom:6px}.lists .empty{padding:15px 5px;font-size:10px}
      .player-actions{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-top:3px}.heart{width:28px;height:28px;border-radius:7px;font:20px/1 system-ui,sans-serif;color:var(--muted)}.heart.liked,.favorites-mark{color:#ed7085}.mode{gap:5px;padding:4px 6px;border-radius:7px;font-size:10px;color:var(--muted)}.mode-icon{font-size:17px;line-height:1}.favorites-drawer{border-top:1px solid var(--line);margin-top:9px}.favorites-row{display:flex;align-items:center;gap:3px}.favorites-row .result{flex:1;min-width:0;width:0}.playlist-tools{display:flex;align-items:center;gap:7px;margin-top:10px;flex-shrink:0;font-size:10px;color:var(--muted)}.playlist-select{min-width:0;flex:1;border:1px solid var(--line);border-radius:7px;background:transparent;color:var(--fg);font:inherit;padding:6px 7px}.playlist-select option{background:#24242b;background:rgb(from var(--base) r g b / 1);color:var(--fg)}.new-playlist{width:28px;height:28px;font-size:18px;border-radius:7px}.new-playlist-form{display:flex;align-items:center;gap:6px;flex-wrap:wrap;margin-top:7px}.playlist-name{flex:1;min-width:0;width:80px;border:1px solid var(--line);border-radius:7px;background:transparent;padding:7px;color:inherit;font:inherit;font-size:11px}.create-playlist,.cancel-playlist{font-size:10px;padding:6px;border-radius:7px}.create-message{flex-basis:100%;font-size:10px;color:var(--muted)}.create-message:empty{display:none}.playlist-status{margin-top:6px}.retry-save{align-self:flex-start}
      .import-toggle{font-size:10px;padding:6px;border:1px solid var(--line);border-radius:7px;white-space:nowrap}.import-form{display:flex;flex-wrap:wrap;gap:6px;margin-top:8px;min-height:0;flex-shrink:0}.import-link{flex-basis:100%;width:100%;min-width:0;resize:vertical;max-height:80px;min-height:45px;border:1px solid var(--line);border-radius:8px;background:transparent;color:inherit;font:inherit;font-size:11px;padding:7px}.import-name{flex:1;min-width:0;width:70px;border:1px solid var(--line);border-radius:7px;background:transparent;padding:6px;font-size:11px}.import-submit,.import-cancel{font-size:10px;padding:6px;border:1px solid var(--line);border-radius:7px}.import-message{flex-basis:100%;margin:0;font-size:10px;color:var(--muted);overflow-wrap:anywhere}.import-message:empty{display:none}
      .lyrics-peek{display:block;text-align:left;width:100%;min-height:22px;margin-top:3px;padding:2px 0;border-radius:5px;font-size:10px;color:var(--muted)}.lyric-current,.lyric-next{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:11px;line-height:18px}.lyric-next{font-size:10px;color:var(--muted)}.full-lyrics{max-height:170px;overflow-y:auto;overscroll-behavior:contain;padding:5px 2px}.lyric-line{margin:0;padding:5px 3px;white-space:pre-wrap;overflow-wrap:anywhere;color:var(--muted);font-size:11px}.lyric-line.active{color:var(--fg);background:var(--soft);border-radius:5px}.load-more{display:block;width:100%;padding:10px;margin:5px 0;border:1px solid var(--line);border-radius:8px;font-size:11px;color:var(--muted)}
      .dock-image{width:30px;height:30px;object-fit:contain;flex-shrink:0;pointer-events:none}.appearance-drawer{border-top:1px solid var(--line);margin-top:9px}.appearance-tools{display:flex;align-items:center;gap:8px;flex-wrap:wrap;padding:3px 2px 10px;font-size:11px;color:var(--muted)}.lyrics-setting{display:flex;align-items:center;gap:6px;flex-basis:100%;padding:3px 0}.lyrics-setting input{accent-color:var(--fg)}.icon-upload,.icon-reset{font-size:10px;padding:5px 8px;border:1px solid var(--line);border-radius:7px}.appearance-message{flex-basis:100%;margin:0;font-size:10px;overflow-wrap:anywhere}.appearance-message:empty{display:none}
      @media(max-width:380px){.player{padding:4px 12px 10px}.search-area{padding:0 12px 10px}.header{padding-left:12px;padding-right:10px}.title{font-size:13px}.window{width:320px}.controls{gap:0}}
    </style>
    <section class="window" aria-label="悬浮音乐播放器">
      <div class="header"><span class="mark" aria-hidden="true">♫</span><span class="brand">桃桃 · 余音</span><button class="minimize" type="button" title="收起，继续播放" aria-label="收起播放器">−</button></div>
      <div class="player">
        <div class="now"><div class="meta"><div class="title">未选择歌曲</div><div class="artist">搜索歌曲或导入歌单</div></div><div class="controls">
          <button class="prev" type="button" aria-label="上一首" title="上一首"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 5h2v14H5zm14 0v14L8 12z"/></svg></button>
          <button class="play" type="button" aria-label="播放" title="播放">▶</button>
          <button class="next" type="button" aria-label="下一首" title="下一首"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M17 5h2v14h-2zM5 5l11 7-11 7z"/></svg></button>
        </div></div>
        <button class="lyrics-peek" type="button" title="展开或收起完整歌词" aria-expanded="false">查看完整歌词 ⌄</button>
        <div class="timeline"><span class="elapsed">0:00</span><input class="seek" type="range" aria-label="播放进度" min="0" max="1000" step="1" value="0" disabled><span class="duration">0:00</span></div>
        <div class="player-actions"><button class="favorite-current heart" type="button" aria-label="喜欢当前歌曲" aria-pressed="false" title="喜欢当前歌曲" disabled>♡</button><button class="mode" type="button" title="切换播放模式"><span class="mode-icon" aria-hidden="true">↻</span><span class="mode-label">列表循环</span></button></div>
        <p class="status" role="status" aria-live="polite"></p><p class="preload-status" style="margin:2px 0 0;font-size:10px;color:var(--muted);overflow-wrap:anywhere" role="status"></p>
      </div>
      <div class="search-area">
        <form class="search-form"><input class="query" type="search" placeholder="输入歌名或歌手" aria-label="歌名或歌手" autocomplete="off" maxlength="120" required><button class="search-button" type="submit">搜索</button></form>
        <div class="playlist-tools"><span>添加到</span><select class="playlist-select" aria-label="选择歌单及歌曲添加位置"></select><button class="new-playlist" type="button" title="新建歌单" aria-label="新建歌单">＋</button><button class="import-toggle" type="button" aria-expanded="false">导入歌单</button></div>
        <form class="import-form" hidden><textarea class="import-link" aria-label="网易云歌单分享文字或链接" placeholder="粘贴网易云歌单分享文字、链接或歌单 ID" maxlength="4000" required></textarea><input class="import-name" aria-label="导入后的歌单名称（选填）" placeholder="歌单名称（选填）" maxlength="40"><button class="import-submit" type="submit">导入</button><button class="import-cancel" type="button">取消</button><p class="import-message" role="status" aria-live="polite"></p></form>
        <form class="new-playlist-form" hidden><input class="playlist-name" aria-label="歌单名称" placeholder="歌单名称" maxlength="40" required autocomplete="off"><button class="create-playlist" type="submit">创建</button><button class="cancel-playlist" type="button">取消</button><span class="create-message" role="status" aria-live="polite"></span></form>
        <p class="playlist-status" role="status" aria-live="polite"></p><button class="retry-save" type="button" hidden>重试保存</button>
        <div class="lists">
          <details class="appearance-drawer"><summary>外观</summary><div class="appearance-tools"><label class="lyrics-setting"><input class="show-dock-lyrics" type="checkbox">显示悬浮歌词条</label><button class="icon-upload" type="button">上传图标</button><button class="icon-reset" type="button">默认音符</button><input class="icon-file" type="file" accept="image/png,image/jpeg,image/webp,image/gif" aria-label="选择悬浮图标" hidden><p class="appearance-message" role="status"></p></div></details>
          <details class="lyrics-drawer" hidden><summary>完整歌词</summary><div class="full-lyrics"></div></details>
          <details class="search-drawer" hidden><summary>搜索结果 <span class="search-count list-count">0</span></summary><p class="search-status" role="status" aria-live="polite">输入歌名或歌手搜索</p><div class="results" role="group" aria-label="搜索结果"></div></details>
          <details class="favorites-drawer"><summary><span class="favorites-mark" aria-hidden="true">♥</span>我喜欢 <span class="favorites-count list-count">0</span></summary><div class="favorites-list" role="group" aria-label="我喜欢的音乐"></div></details>
          <details class="playlist-drawer" open><summary><span class="playlist-title">我的歌单</span><span class="playlist-count list-count">0</span></summary><div class="playlist-list" role="group" aria-label="我的歌单"></div></details>
        </div>
      </div>
    </section>
    <button class="dock paused" type="button" aria-label="展开音乐播放器" title="点击展开，拖动可移动" hidden><span class="dock-note" aria-hidden="true">♫</span><img class="dock-image" alt="" hidden><span class="dock-lyrics"><span class="lyric-current">播放后显示歌词</span><span class="lyric-next">点击展开完整歌词</span></span></button>
  `;
  const $ = selector => root.querySelector(selector);
  const clock = value => Number.isFinite(value) && value >= 0
    ? Math.floor(value / 60) + ':' + String(Math.floor(value % 60)).padStart(2, '0') : '0:00';
  function text(value) { return String(value ?? '').slice(0, 240); }
  function safeURL(value, base = API) {
    const url = new URL(value, base);
    if (!['http:', 'https:'].includes(url.protocol) || url.username || url.password) throw new Error('无效音频地址');
    if (host.location.protocol === 'https:' && url.protocol === 'http:') url.protocol = 'https:';
    return url;
  }
  function keyOf(title, artist) {
    const normal = s => s.normalize('NFKC').toLowerCase().replace(/\s+/g, '');
    const names = artist.split(/[,，、/&／]/).map(normal).filter(Boolean).sort();
    return normal(title) + '|' + names.join('/');
  }
  function makeCandidate(song, platform) {
    if (!song || typeof song !== 'object' || typeof song.url !== 'string' || !song.url) return null;
    try {
      const url = safeURL(song.url);
      const title = text(song.name || song.title || '未命名歌曲');
      const artist = text(Array.isArray(song.artist) ? song.artist.join(' / ') : song.artist || song.author || '');
      const server = ['netease', 'tencent'].includes(url.searchParams.get('server')) ? url.searchParams.get('server') : platform;
      const id = text(song.id || song.sourceId || url.searchParams.get('id') || '');
      // 接口提供的是按需跳转地址，播放时重新取得签名链接，不持久化临时 MP3 地址。
      if (url.searchParams.get('type') === 'url') { url.searchParams.set('br', '128'); url.searchParams.set('redirect', '1'); }
      const lrc = typeof song.lrc === 'string' && song.lrc ? safeURL(song.lrc).href : '';
      return { title, artist, server, id, url: url.href, lrc };
    } catch { return null; }
  }
  function savedGroup(value) {
